struct algorithm
{
    struct object     hdr;
    enum alg_id       id;
    enum chain_mode   chain_mode;
    ULONG             flags;
    enum ecc_curve_id curve_id;
};

struct asymmetric_key
{
    ULONG bitlen;     /* key strength for ECC keys */
    union
    {
        struct rsa_key rsa;
        struct ecc_key ecc;
        struct dsa_key dsa;
    };
};

enum chain_mode
{
    CHAIN_MODE_CBC,
    CHAIN_MODE_ECB,
    CHAIN_MODE_CFB,
    CHAIN_MODE_CCM,
    CHAIN_MODE_GCM,
};

struct gcm_key
{
    SYMCRYPT_GCM_EXPANDED_KEY handle;
    SYMCRYPT_GCM_STATE        state;
};

struct key
{
    struct object hdr;
    enum alg_id   alg_id;
    ULONG         flags;
    union
    {
        struct symmetric_key s;
        struct asymmetric_key a;
    };
};

